package com.metabuild.modules.admin.profile.controller;
import com.metabuild.modules.admin.auth.api.CurrentAuthorizationProvider;import com.metabuild.modules.admin.profile.application.*;import com.metabuild.shared.kernel.BadRequest;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profile") public final class ProfileController {private final ProfileService service;private final CurrentAuthorizationProvider current;public ProfileController(ProfileService service,CurrentAuthorizationProvider current){this.service=service;this.current=current;}private UUID user(){return current.current().userId();}@GetMapping public ProfileView get(){return service.get(user());}@PutMapping public ProfileView update(@RequestBody ProfileUpdate x){return service.update(user(),x);}@GetMapping("/security") public SecuritySettings security(){return service.security(user());}@PatchMapping("/security") public SecuritySettings security(@RequestBody SecuritySettings x){return service.updateSecurity(user(),x);}@PostMapping("/password") @ResponseStatus(HttpStatus.NO_CONTENT) public void password(@RequestBody PasswordWrite x){if(x==null)throw new BadRequest(()->"request.validation.failed","Request body is required");service.changePassword(user(),x.currentPassword(),x.newPassword());}@GetMapping("/preferences") public PreferenceView preferences(){return service.preferences(user());}@PutMapping("/preferences") public PreferenceView preferences(@RequestBody PreferenceView x){return service.updatePreferences(user(),x);}@GetMapping("/devices") public List<LoginDeviceView> devices(){return service.devices(user());}@DeleteMapping("/devices/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable String id){service.removeDevice(user(),id);}public record PasswordWrite(String currentPassword,String newPassword){} }
